package com.foodmaker.pizzamaker

import android.graphics.*
import android.os.SystemClock
import kotlin.math.sin

class PrepPainter(private val a:CrayonArt,private val f:PizzaPainter){
    private val p=Paint(Paint.ANTI_ALIAS_FLAG)
    fun draw(c:Canvas,g:GameState){when(g.stage){Stage.WELCOME->welcome(c);Stage.MIX->mix(c,g);Stage.ROLL->roll(c,g);Stage.SAUCE->sauce(c,g);Stage.CHEESE->cheese(c,g);else->{}}}
    private fun welcome(c:Canvas){a.box(c,RectF(90f,165f,990f,590f),55f,Color.argb(235,255,247,222),300);a.text(c,"피자 메이커",540f,305f,82f,Color.rgb(231,74,47));a.text(c,"반죽부터 한 입까지 직접 만들어봐",540f,390f,35f);f.pizza(c,540f,875f,330f);listOf(ToppingPiece(ToppingType.PEPPERONI,-.28f,-.18f,-12f,1.15f),ToppingPiece(ToppingType.MUSHROOM,.24f,-.22f,15f,1f),ToppingPiece(ToppingType.PEPPER,-.08f,.24f,18f,.95f),ToppingPiece(ToppingType.OLIVE,.3f,.18f,0f,1f),ToppingPiece(ToppingType.ONION,-.33f,.18f,-18f,1f)).forEach{f.topping(c,it,540f,875f,330f)};val q=(sin(SystemClock.uptimeMillis()/280.0)*.04+1).toFloat();c.save();c.scale(q,q,540f,1455f);a.box(c,RectF(260f,1375f,820f,1535f),65f,Color.rgb(250,196,76),310);a.text(c,"만들기 시작",540f,1476f,51f);c.restore();a.text(c,"손가락으로 직접 요리해요",540f,1655f,31f,Color.rgb(92,77,62))}
    private fun mix(c:Canvas,g:GameState){a.bowl(c,540f,1160f,570f,330f);if(g.mixAdded[0]){p.color=Color.rgb(247,235,205);p.style=Paint.Style.FILL;c.drawOval(RectF(360f,1080f,720f,1245f),p)};if(g.mixAdded[1]){p.color=Color.argb(120,120,200,230);c.drawOval(RectF(390f,1100f,690f,1240f),p)};if(g.mixAdded[2]){p.color=Color.argb(130,230,205,65);c.drawOval(RectF(425f,1120f,655f,1248f),p)};if(g.mixAdded.all{it}){a.circle(c,540f,1160f,130f+g.stir*35f,Color.rgb(238,207,154),350);a.spoon(c,if(g.toolHeld)g.touchX else 700f,if(g.toolHeld)g.touchY else 1080f,-28f);if(g.stir>=1)hint(c,540f,1440f,540f,1580f)}else{a.flour(c,230f,640f);a.cup(c,540f,640f);a.oil(c,850f,640f);a.text(c,"밀가루",230f,815f,31f);a.text(c,"물",540f,815f,31f);a.text(c,"오일",850f,815f,31f);if(SystemClock.uptimeMillis()-g.lastInput>1500)hint(c,230f,850f,470f,1030f)}}
    private fun roll(c:Canvas,g:GameState){f.dough(c,540f,1120f,215f+g.roll*120f);a.roller(c,if(g.toolHeld)g.touchX else 540f,if(g.toolHeld)g.touchY else 1420f,if(g.toolHeld)((g.touchX-g.prevX)*.18f).coerceIn(-12f,12f) else -4f);if(g.roll>.92f)hint(c,540f,1545f,540f,1675f)}
    private fun sauce(c:Canvas,g:GameState){f.dough(c,540f,1050f,335f);c.save();c.clipPath(Path().apply{addCircle(540f,1050f,285f,Path.Direction.CW)});p.style=Paint.Style.FILL;g.sauceMarks.forEachIndexed{i,m->p.color=if(i%3==0)Color.rgb(239,66,43) else Color.rgb(224,53,39);c.drawCircle(m.x,m.y,55f+(i%4)*3,p)};c.restore();a.bowl(c,230f,1580f,260f,155f,Color.rgb(242,106,78));a.text(c,"토마토 소스",230f,1730f,30f);a.spoon(c,if(g.toolHeld)g.touchX else 760f,if(g.toolHeld)g.touchY else 1550f,-18f);if(g.sauce>.82f)hint(c,540f,1460f,540f,1600f)}
    private fun cheese(c:Canvas,g:GameState){f.pizza(c,540f,1040f,340f,1f,0f);c.save();c.clipPath(Path().apply{addCircle(540f,1040f,278f,Path.Direction.CW)});p.style=Paint.Style.STROKE;p.strokeCap=Paint.Cap.ROUND;g.cheeseBits.forEachIndexed{i,b->p.color=if(i%3==0)Color.rgb(255,239,150) else Color.rgb(255,213,72);p.strokeWidth=13f;val r=Math.toRadians(b.rotation.toDouble());val dx=kotlin.math.cos(r).toFloat()*b.length/2;val dy=kotlin.math.sin(r).toFloat()*b.length/2;c.drawLine(b.x-dx,b.y-dy,b.x+dx,b.y+dy,p)};c.restore();a.shaker(c,if(g.toolHeld)g.touchX else 790f,if(g.toolHeld)g.touchY else 1530f,if(g.toolHeld)-15f else 9f);if(g.cheese>.78f)hint(c,540f,1450f,540f,1600f)}
    private fun hint(c:Canvas,x1:Float,y1:Float,x2:Float,y2:Float){val q=(.55+.45*((sin(SystemClock.uptimeMillis()/220.0)+1)/2)).toFloat();a.arrow(c,x1,y1,x2,y2,(120+120*q).toInt())}
}
